OBJETO_SISTEMA.DS_SCRIPT_CRIACAO:
CREATE OR REPLACE FUNCTION CMDKLTDA_FN_SOMAR2(
    p_num1 NUMBER,
    p_num2 NUMBER
)
RETURN NUMBER
IS
v number;
b varchar2;
BEGIN
select cd_pessoa_fisica into v from pessoa_fisica where cd_pessoa_fisica = 100001;
SELECT cd_estabelecimento into v
          FROM ATENDIMENTO_PACIENTE
         WHERE nr_atendimento = 829238;
    RETURN p_num1 + p_num2;
END;
/

